import { villages,categories,comparisonDimensions,projectTypes,atlasApps,atlasMaturity,atlasBibliography,provenance,getVillage,getObservation,filterObservations,compareVillages,buildDesignGuide,observationIndex } from './atlas-data.mjs';

const BASE='/education/research-labs/',FIELD=BASE+'rural-architecture/',ASSETS=BASE+'assets/';
const $=(s,r=document)=>r.querySelector(s),all=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',back:'<path d="M20 12H5m6-6-6 6 6 6"/>',up:'<path d="M5 19 19 5M5 5h14v14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',play:'<path d="m9 5 11 7-11 7z"/>',pause:'<path d="M8 5v14M16 5v14"/>',replay:'<path d="M4 10a8 8 0 1 1 1 8M4 4v6h6"/>',chevron:'<path d="m6 9 6 6 6-6"/>',swap:'<path d="M4 8h16m-5-5 5 5-5 5M20 17H4m5-5-5 5 5 5"/>',print:'<path d="M7 9V3h10v6M7 17H3V9h18v8h-4M7 14h10v7H7z"/>',atlas:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zm6-2v16m6-14v16"/>',compare:'<path d="M3 4h7v16H3zm11 0h7v16h-7"/>',guide:'<path d="M4 3h12l4 4v14H4zm4 6h8m-8 4h8m-8 4h5"/>',layers:'<path d="m3 8 9-5 9 5-9 5zm0 5 9 5 9-5M3 18l9 5 9-5"/>',roof:'<path d="m2 12 10-9 10 9M5 10v11h14V10"/>',window:'<path d="M4 3h16v18H4zm8 0v18M4 12h16"/>',court:'<path d="M3 3h18v18H3zm6 6h6v6H9z"/>',path:'<path d="M4 21V14h5V8h6V3h5"/>',settlement:'<path d="m2 10 5-4 5 4m-8-1v7h6V9m4-2 4-4 4 4m-7-1v8h6V6M5 21h15"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.arrow}</svg>`;
const image=v=>ASSETS+'rural-architecture/'+v.image+'.png';
const appId=location.pathname.split('/').find(p=>atlasApps.some(a=>a.id===p)),appInfo=atlasApps.find(a=>a.id===appId),params=new URLSearchParams(location.search);
const validVillage=id=>villages.some(v=>v.id===id);
let villageId=validVillage(params.get('v'))?params.get('v'):villages[0].id,query='',category='',selectedObservation=params.get('obs')||getVillage(villageId).observations[0].id,boardView='study';
if(!getObservation(villageId,selectedObservation))selectedObservation=getVillage(villageId).observations[0].id;
let leftId=validVillage(params.get('a'))?params.get('a'):villages[0].id,rightId=validVillage(params.get('b'))?params.get('b'):villages[1].id,dimension=categories.some(c=>c.id===params.get('dimension'))?params.get('dimension'):'materials';
let projectType='new',guideVillageId=villageId,activeRecommendation=0,designBoardView='study',generatedGuide=buildDesignGuide(guideVillageId,projectType);
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
let motion=!motionPreference.matches,guideOpen=false,guideStep=0,guidePlaying=false,guideTimer,toastTimer;
let imageFailures=new Set(),guideExampleSnapshot=null;
const app=$('#app');
function brand(){return `<a class="brand brand-logo" href="/" aria-label="Barchinet Global home"><img src="${ASSETS}barchinet-global.svg" width="900" height="230" alt="Barchinet Global"><small>RESEARCH LABS / EDUCATION</small></a>`}
function header(){return `<header class="rural-header">${brand()}<a class="rural-back" href="${appInfo?FIELD:BASE}">${icon('back')} ${appInfo?'Rural Architecture':'Research Labs'}</a></header>`}
function footer(){return `<footer class="rural-footer"><span><a href="/">Barchinet Global</a> / Education / Research Labs / Rural Architecture</span><span>Synthetic collection · No real locations</span><a href="/website-privacy.html">Website privacy</a></footer>`}
function moduleNav(){return `<div class="rural-modulebar"><nav class="rural-modules" aria-label="Rural architecture applications">${atlasApps.map((a,i)=>`<a href="${FIELD}${a.id}/" class="${a.id===appId?'active':''}" ${a.id===appId?'aria-current="page"':''}>${icon(['atlas','compare','guide'][i])}${['Atlas','Compare','Design guide'][i]}</a>`).join('')}</nav><div class="rural-status"><strong>Synthetic collection</strong><span>3 villages · 30 observations · Read-only</span></div></div>`}
function shell(content){document.title=appInfo.title+' — Barchinet Global Research Labs';return `<div class="rural-shell">${header()}<main id="main"><section class="rural-titlebar"><div><div class="rural-eyebrow">Rural Architecture / ${appInfo.number}</div><h1>${esc(appInfo.title)}</h1><p>${esc(appInfo.mission)}</p></div><div class="rural-title-actions"><button class="button light" id="rural-maturity">Maturity · 1/6</button><a class="button light" href="#rural-sources">Sources & method</a></div></section>${moduleNav()}${coachHtml()}${content}${sourcesHtml()}</main>${footer()}</div><dialog class="rural-dialog" id="rural-dialog" aria-labelledby="rural-dialog-title"></dialog><div class="rural-toast" id="rural-toast" role="status" aria-live="polite" hidden></div>`}
function villagesOptions(selected){return villages.map(v=>`<option value="${v.id}" ${selected===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}
function villageContext(){const v=getVillage(villageId);return `<div class="rural-context"><div class="rural-villages" role="group" aria-label="Select a fictional village">${villages.map(v=>`<button data-village="${v.id}" class="${v.id===villageId?'active':''}" aria-pressed="${v.id===villageId}">${esc(v.name)}</button>`).join('')}</div><div class="rural-context-copy"><strong>${esc(v.climate)}</strong><span>${esc(v.setting)} · 10 observations</span></div></div>`}
function renderCollection(){document.title='Rural Architecture — Barchinet Global Research Labs';app.innerHTML=`<div class="rural-shell">${header()}<main id="main"><section class="rural-collection-heading"><div><div class="rural-eyebrow">Education / Research Labs / Rural Architecture</div><h1>Rural Architecture</h1><p>A source-led workbench for reading architectural patterns. Explore a village, compare the evidence, then trace a design prompt back to the observation that informed it.</p></div><div class="rural-collection-count"><span>3 fictional villages</span><span>30 synthetic observations</span><span>3 independent applications</span></div></section><section class="rural-app-launchers" aria-label="Choose an application">${atlasApps.map(a=>`<a class="rural-launcher" href="${FIELD}${a.id}/"><span class="rural-launcher-num">${a.number} / RESEARCH WORKSPACE</span><h2>${esc(a.title)}</h2><p>${esc(a.description)}</p><span class="rural-launcher-bottom">${esc(a.primary)} ${icon('arrow')}</span></a>`).join('')}</section><section class="rural-collection-studies" aria-label="The synthetic study collection">${villages.map(v=>`<article class="rural-study-card"><div class="rural-study-card-image"><img src="${image(v)}" alt="AI-generated conceptual study of fictional ${esc(v.name)}" loading="lazy"></div><div class="rural-study-card-body"><div class="rural-eyebrow">${esc(v.climate)}</div><h3>${esc(v.name)}</h3><p>${esc(v.summary)}</p><small>10 synthetic observations · No geographic coordinates</small><a href="${FIELD}village-atlas/?v=${v.id}">Inspect the records ${icon('arrow')}</a></div></article>`).join('')}</section><section class="rural-source-note"><h2>Keep the evidence<br>and the suggestion distinct.</h2><div><p>${esc(provenance.notice)}</p><p style="margin-top:10px">The observation set is preserved from the transferred Sample.html and translated to English. The official publications explain documentation and conservation approaches; they are not sources for the fictional village records. Research maturity: <strong>Research — Interactive Demo · 1/6.</strong></p></div></section></main>${footer()}</div>`;bindImages()}

/* Architectural schematics provide a legible fallback and component focus.
 * They are interpretive teaching drawings, without dimensions or a scale.
 */
function drawing(v,focus='materials',drawingId='default'){const hot=v.id==='aftab-dasht',wet=v.id==='meh-darreh';const ground=hot?'#e9ddc9':wet?'#dbe5d4':'#dde2d8';const wall=hot?'#d2b184':wet?'#dfdbc6':'#d1d3c2';const roof=hot?'#cfbb96':wet?'#7d9585':'#8e9b92';const cls=c=>`component ${focus===c?'focus':''}`;return `<svg class="drawing-layer rural-drawing" viewBox="0 0 720 440" role="img" aria-label="Interpretive architectural schematic of ${esc(v.name)}, no scale or measured geometry"><defs><pattern id="hatch-${v.code}-${drawingId}" patternUnits="userSpaceOnUse" width="9" height="9"><path d="M0 9 9 0" stroke="#bcc5ad" stroke-width=".6"/></pattern></defs><rect width="720" height="440" fill="#edf0e5"/><path d="M40 340 345 155 680 285 380 415Z" fill="${ground}"/><path d="M60 350 375 165M90 365 405 180M120 380 435 195M150 395 465 210M180 410 495 225" stroke="#c7d2bc" stroke-width=".6"/><g class="${cls('paths')}" stroke="#87987d" stroke-width="1.4" fill="none"><path d="M80 368 267 257 353 291 577 158" stroke-width="13" stroke="#c1c7ad"/>${hot?'':`<path d="M162 308l34 14m-18-25 34 14m-18-25 34 14m-18-25 34 14"/>`}</g><g class="${cls('settlement')}" fill="none" stroke="#a6b498" stroke-width="1.2"><path d="M93 278 341 129 630 245 375 399Z" stroke-dasharray="5 5"/><path d="M114 287 359 140M140 304 386 157"/></g><g class="${cls('materials')}" fill="${wall}" stroke="#64785e" stroke-width="1.3"><path d="M185 278V179l143-85 143 59v111l-142 86Z"/><path d="m328 94 143 59v111l-142 86V205l-144 73V179Z" opacity=".6"/>${wet?'<path d="M185 278v18l144 72 142-86v-18L329 350Z" fill="#abb5a1"/>':''}</g><g class="${cls('roof')}" stroke="#586f59" stroke-width="1.6" fill="${roof}">${hot?'<path d="m175 174 151-90 157 64-153 93Z"/><path d="m175 174v-12l152-91 156 63v14l-157-64-151 90Z" fill="#d6bf98"/>':'<path d="m164 186 153-151 177 102-149 102Z"/><path d="m317 35 28 204 149-102Z" fill="#a5b3a2"/><path d="m174 182 145-136m-119 151L321 59m-95 154L323 73m-71 156 73-142m-46 155 48-141" fill="none" stroke="#879d86" stroke-width=".7"/>'}</g><g class="${cls('openings')}" fill="#647f69" stroke="#405d46" stroke-width="1.1"><path d="m222 220 29-17v33l-29 17Z"/><path d="m274 190 26-15v34l-26 15Z"/><path d="m368 230 35 15v32l-35-15Z"/><path d="m429 249 25 11v30l-25-11Z"/><path d="m304 291 27-16v56l-27 16Z"/></g><g class="${cls('courtyard')}" fill="url(#hatch-${v.code}-${drawingId})" stroke="#7f9674" stroke-width="1.2"><path d="m415 313 77-47 111 43-78 48Z"/>${hot?'<path d="m492 266 111 43v-19l-111-43Z" fill="#cdb385"/><path d="m603 309-78 48v-19l78-48Z" fill="#c0a77d"/>':'<path d="m479 313 15-24 16 24m-10-2v23m41-8 14-23 15 23m-9-2v22" fill="#91ac7d"/>'}</g><path class="guide-line" d="M${v.markers[focus].x*7.2} ${v.markers[focus].y*4.4}L616 70H679" fill="none" stroke="#a6784b" stroke-width="1.4"/><text x="45" y="42" font-size="10" fill="#7c8d71" letter-spacing="1.2">INTERPRETIVE STUDY / NO SCALE</text><text x="615" y="60" font-size="10" fill="#8d7654" text-anchor="end">${esc(categories.find(c=>c.id===focus).label.toUpperCase())}</text></svg>`}
function boardHtml(v,focus,{pins=false,view='study',id='main'}={}){if(view==='index')return mapHtml();const point=v.markers[focus];return `<div class="rural-board-canvas ${imageFailures.has(v.id)||view==='diagram'?'':'has-image'}" data-board="${id}">${drawing(v,focus,id)}${view!=='diagram'&&!imageFailures.has(v.id)?`<img data-study-image="${v.id}" src="${image(v)}" alt="AI-generated conceptual architectural study of fictional ${esc(v.name)}">`:''}${pins?categories.map((c,i)=>`<button class="rural-marker ${c.id===focus?'active':''}" style="--x:${v.markers[c.id].x};--y:${v.markers[c.id].y}" data-component="${c.id}" aria-label="Inspect ${esc(c.label)} observations" aria-pressed="${c.id===focus}"><span class="pin-num">${i+1}</span>${c.id===focus?`<span class="pin-label">${esc(c.label)}</span>`:''}</button>`).join(''):''}<div class="focus-ring" style="--x:${point.x};--y:${point.y}"></div><div class="rural-overlay-label"><strong>${esc(categories.find(c=>c.id===focus).label)}</strong><span>${esc(v.facts[focus])}</span></div></div>`}
function mapHtml(){return `<div class="rural-board-canvas rural-index"><svg class="rural-map" viewBox="0 0 720 440" preserveAspectRatio="none" aria-hidden="true"><rect width="720" height="440" fill="#edf1e5"/><g fill="none" stroke="#c6d5b8" stroke-width="1"><path d="M-35 105Q198-45 397 115T780 92M-35 140Q198-10 397 150T780 127M-35 175Q198 25 397 185T780 162M-35 210Q198 60 397 220T780 197M-35 245Q198 95 397 255T780 232M-35 280Q198 130 397 290T780 267M-35 315Q198 165 397 325T780 302M-35 350Q198 200 397 360T780 337"/></g></svg><div class="rural-index-stamp">Non-geographic study index<br><span>Selection only · no real coordinates</span></div>${villages.map(v=>`<button class="rural-index-point ${villageId===v.id?'selected':''}" style="--x:${v.map.x};--y:${v.map.y}" data-map-village="${v.id}" aria-label="Select fictional ${esc(v.name)}" aria-pressed="${villageId===v.id}"><span class="index-point-dot" aria-hidden="true"></span><span class="index-point-label"><strong>${esc(v.name)}</strong><small>${esc(v.climate)}</small></span></button>`).join('')}</div>`}
function bindImages(){all('[data-study-image]').forEach(img=>{img.onerror=()=>{imageFailures.add(img.dataset.studyImage);img.parentElement.classList.remove('has-image');img.hidden=true}});all('.rural-study-card-image img').forEach(img=>img.onerror=()=>{const v=villages.find(v=>image(v)===img.getAttribute('src'));if(v)img.parentElement.innerHTML=drawing(v)})}

/* Village Atlas: controls, source records and visible components stay linked. */
function atlasWorkspace(){return `<div id="atlas-context">${villageContext()}</div><div class="rural-workspace"><aside class="record-browser" aria-label="Observation browser"><div class="record-filters"><h2 class="rural-panel-title">Observation browser <span>10 records</span></h2><label class="rural-field">Search observations<input class="rural-input" id="atlas-search" type="search" placeholder="Material, roof, courtyard…" maxlength="100" value="${esc(query)}"></label><label class="rural-field">Component<select class="rural-select" id="atlas-category"><option value="">All components</option>${categories.map(c=>`<option value="${c.id}" ${c.id===category?'selected':''}>${esc(c.label)}</option>`).join('')}</select></label></div><div class="record-list-wrap"><p class="rural-filter-summary" id="record-count" aria-live="polite"></p><div class="record-list" id="atlas-records"></div></div></aside><section class="rural-study" aria-label="Architectural study board"><div class="rural-board-toolbar"><div class="rural-board-tabs" role="group" aria-label="Study board view"><button data-board-view="study" class="${boardView==='study'?'active':''}" aria-pressed="${boardView==='study'}">Study</button><button data-board-view="diagram" class="${boardView==='diagram'?'active':''}" aria-pressed="${boardView==='diagram'}">Diagram</button><button data-board-view="index" class="${boardView==='index'?'active':''}" aria-pressed="${boardView==='index'}">Index</button></div><span class="rural-focus-title" id="board-focus-title"></span></div><div id="atlas-board"></div><div class="rural-board-caption"><span id="atlas-board-caption">Conceptual illustration · Markers link to synthetic records, not measured locations</span><button class="text-button" id="reset-atlas">Reset view</button></div></section><aside class="rural-inspector" id="atlas-inspector" aria-label="Selected observation"></aside></div>`}
function renderAtlas(){app.innerHTML=shell(atlasWorkspace());bindCommon();bindAtlasControls();updateAtlas()}
function bindAtlasControls(){all('[data-village]').forEach(b=>b.onclick=()=>{pauseForUser();selectVillage(b.dataset.village)});$('#atlas-search').oninput=e=>{pauseForUser();query=e.target.value;updateAtlas()};$('#atlas-category').onchange=e=>{pauseForUser();category=e.target.value;updateAtlas()};all('[data-board-view]').forEach(b=>b.onclick=()=>{pauseForUser();boardView=b.dataset.boardView;all('[data-board-view]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});updateAtlasBoard()});$('#reset-atlas').onclick=()=>{pauseForUser();query='';category='';boardView='study';selectedObservation=getVillage(villageId).observations[0].id;$('#atlas-search').value='';$('#atlas-category').value='';all('[data-board-view]').forEach(b=>{b.classList.toggle('active',b.dataset.boardView==='study');b.setAttribute('aria-pressed',String(b.dataset.boardView==='study'))});updateAtlas()}}
function selectVillage(id,fromMap=false){villageId=id;query='';category='';selectedObservation=getVillage(id).observations[0].id;$('#atlas-context').innerHTML=villageContext();all('[data-village]').forEach(b=>b.onclick=()=>{pauseForUser();selectVillage(b.dataset.village)});$('#atlas-search').value='';$('#atlas-category').value='';updateAtlas();$(fromMap?'[data-map-village="'+id+'"]':'[data-village="'+id+'"]')?.focus({preventScroll:true})}
function updateAtlas(){const v=getVillage(villageId),found=filterObservations(villageId,{query,category});if(!found.some(o=>o.id===selectedObservation))selectedObservation=found[0]?.id||null;$('#record-count').textContent=`${found.length} of ${v.observations.length} synthetic observations`;$('#atlas-records').innerHTML=found.length?found.map(o=>`<button class="rural-record ${o.id===selectedObservation?'active':''}" data-record="${o.id}" aria-pressed="${o.id===selectedObservation}"><span class="record-id">${o.id}</span><strong>${esc(o.title)}</strong><span class="record-category">${esc(categories.find(c=>c.id===o.category).label)} · Synthetic</span></button>`).join(''):'<div class="record-empty">No observations match this search.<br>Try a different term or component.<br><button class="rural-toolbar-button" id="clear-atlas-filter">Clear filters</button></div>';all('[data-record]').forEach(b=>b.onclick=()=>{pauseForUser();selectedObservation=b.dataset.record;updateAtlas();$(`[data-record="${selectedObservation}"]`)?.focus({preventScroll:true})});const clear=$('#clear-atlas-filter');if(clear)clear.onclick=()=>{pauseForUser();query='';category='';$('#atlas-search').value='';$('#atlas-category').value='';updateAtlas();$('#atlas-search').focus({preventScroll:true})};updateAtlasBoard();updateAtlasInspector()}
function updateAtlasBoard(){const v=getVillage(villageId),o=selectedObservation?getObservation(villageId,selectedObservation):null,focus=o?.category||category||'materials';$('#atlas-board').innerHTML=boardHtml(v,focus,{pins:true,view:boardView});$('#board-focus-title').textContent=o?`${o.id} / ${categories.find(c=>c.id===focus).label}`:'No selected record';$('#atlas-board-caption').textContent=boardView==='index'?'Non-geographic study index · No real coordinates, distances or regional relationships':boardView==='diagram'?'Interpretive teaching drawing · No scale, measured geometry or field survey':'AI-generated conceptual study · Markers link to records, not measured locations';all('[data-component]').forEach(b=>b.onclick=()=>{pauseForUser();category=b.dataset.component;query='';$('#atlas-category').value=category;$('#atlas-search').value='';selectedObservation=getVillage(villageId).observations.find(o=>o.category===category)?.id;updateAtlas();$(`[data-component="${category}"]`)?.focus({preventScroll:true})});all('[data-map-village]').forEach(b=>{const choose=()=>{pauseForUser();selectVillage(b.dataset.mapVillage,true)};b.onclick=choose;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose()}}});bindImages()}
function updateAtlasInspector(){const v=getVillage(villageId),o=selectedObservation?getObservation(villageId,selectedObservation):null;if(!o){$('#atlas-inspector').innerHTML='<div class="rural-evidence-head"><span>Evidence record</span><span class="evidence-badge">Synthetic</span></div><h2>No selected observation</h2><p>Clear or adjust the filters to inspect another record. The collection contains ten observations for this village.</p>';return}$('#atlas-inspector').innerHTML=`<div class="rural-evidence-head"><span>${o.id}</span><span class="evidence-badge">Synthetic</span></div><h2>${esc(o.title)}</h2><p>${esc(o.text)}</p><dl class="record-provenance"><dt>Component</dt><dd>${esc(categories.find(c=>c.id===o.category).label)}</dd><dt>Village</dt><dd>${esc(v.name)} · ${esc(v.climate)}</dd><dt>Source</dt><dd>Sample.html, observation ${o.sourceIndex} / 10 · English translation</dd><dt>Field status</dt><dd>No real capture date, coordinates or reviewer</dd></dl><div class="rural-question"><strong>A question to investigate</strong><p>${esc(v.question)}</p></div><div class="rural-links"><a href="${FIELD}village-comparison/?a=${v.id}&b=${villages.find(x=>x.id!==v.id).id}&dimension=${o.category}">Compare this component ${icon('arrow')}</a><a href="${FIELD}design-guide/?v=${v.id}">Trace a design prompt ${icon('arrow')}</a></div>`}

/* Comparison exposes both records without ranking their quality. */
function comparisonBody(){return `<div class="comparison-controls"><label class="rural-field">Village A<select class="rural-select" id="compare-a">${villagesOptions(leftId)}</select></label><button class="comparison-swap" id="swap-villages" aria-label="Swap the compared villages">${icon('swap')}</button><label class="rural-field">Village B<select class="rural-select" id="compare-b">${villagesOptions(rightId)}</select></label></div><div class="comparison-layout"><aside class="comparison-lenses" aria-label="Comparison component"><h2>Read one dimension</h2>${comparisonDimensions.map(c=>`<button data-dimension="${c.id}" class="${c.id===dimension?'active':''}" aria-pressed="${c.id===dimension}">${icon(c.symbol)} ${esc(c.label)}</button>`).join('')}</aside><section class="comparison-content" id="comparison-content" aria-live="polite"></section></div>`}
function renderComparison(){app.innerHTML=shell(comparisonBody());bindCommon();$('#compare-a').onchange=e=>{pauseForUser();leftId=e.target.value;updateComparison()};$('#compare-b').onchange=e=>{pauseForUser();rightId=e.target.value;updateComparison()};$('#swap-villages').onclick=()=>{pauseForUser();[leftId,rightId]=[rightId,leftId];$('#compare-a').value=leftId;$('#compare-b').value=rightId;updateComparison()};all('[data-dimension]').forEach(b=>b.onclick=()=>{pauseForUser();dimension=b.dataset.dimension;updateComparison()});updateComparison()}
function evidenceChips(village,evidence){return `<div class="evidence-chips">${evidence.map(o=>`<button class="evidence-chip" data-evidence-village="${village.id}" data-evidence-id="${o.id}" aria-label="Read evidence ${o.id}: ${esc(o.title)}">${o.id}</button>`).join('')}</div>`}
function updateComparison(){all('[data-dimension]').forEach(b=>{b.classList.toggle('active',b.dataset.dimension===dimension);b.setAttribute('aria-pressed',String(b.dataset.dimension===dimension))});const comparison=compareVillages(leftId,rightId);if(comparison.duplicate){$('#comparison-content').innerHTML='<div class="comparison-duplicate"><h2>Choose two different villages.</h2><p>The same village is selected on both sides.<br>Select another village to compare two evidence sets.</p></div>';return}const row=comparison.rows.find(r=>r.id===dimension),label=categories.find(c=>c.id===dimension).label;$('#comparison-content').innerHTML=`<div class="comparison-focus-bar"><strong>${esc(label)} / two evidence sets</strong><span>${row.left.evidence.length} records from A · ${row.right.evidence.length} from B</span></div><div class="comparison-scenes">${[['A',comparison.left,row.left],['B',comparison.right,row.right]].map(([side,v,record])=>`<article class="comparison-village"><div class="comparison-village-head"><h2>${esc(v.name)}</h2><span>${side} / ${esc(v.climate)}</span></div>${boardHtml(v,dimension,{id:side})}<div class="comparison-reading"><span class="dimension-label">${esc(label)} / Recorded pattern</span><h3>${esc(record.text)}</h3>${evidenceChips(v,record.evidence)}</div></article>`).join('')}</div><div class="comparison-question"><div><h3>What would you investigate next?</h3><p>These patterns describe two fictional contexts. Ask which cultural, climatic and site evidence would be needed before transferring a pattern to another project. Geographic closeness alone would not establish similarity.</p></div><span>2 villages · 20 observations<br>No performance ranking</span></div><details class="comparison-matrix"><summary>View all six comparison dimensions ${icon('chevron')}</summary>${comparison.rows.map(r=>`<div class="comparison-row"><div>${esc(r.label)}</div><div><strong>${esc(comparison.left.name)}</strong>${esc(r.left.text)}${evidenceChips(comparison.left,r.left.evidence)}</div><div><strong>${esc(comparison.right.name)}</strong>${esc(r.right.text)}${evidenceChips(comparison.right,r.right.evidence)}</div></div>`).join('')}</details>`;bindEvidenceButtons();bindImages()}
function bindEvidenceButtons(){all('[data-evidence-id]').forEach(b=>b.onclick=()=>{pauseForUser();showEvidence(b.dataset.evidenceVillage,b.dataset.evidenceId)})}
function showEvidence(vId,oId){const v=getVillage(vId),o=getObservation(vId,oId);if(!o)return;dialog(o.id+' / '+o.title,`<div class="evidence-badge" style="display:inline-block;margin-bottom:15px">Synthetic observation</div><p>${esc(o.text)}</p><dl class="record-provenance"><dt>Village</dt><dd>${esc(v.name)} · ${esc(v.climate)}</dd><dt>Transferred source</dt><dd>Sample.html, observation ${o.sourceIndex} of 10 · translated to English</dd><dt>Geographic status</dt><dd>Fictional village; no real coordinates</dd></dl><div class="rural-links"><a href="${FIELD}village-atlas/?v=${v.id}&obs=${o.id}">Inspect this record in Village Atlas ${icon('arrow')}</a></div>`)}

/* Design Guide makes a small, explicit rule system inspectable. */
function designBody(){return `<div class="design-controls"><label class="rural-field">Fictional village<select class="rural-select" id="design-village">${villagesOptions(guideVillageId)}</select></label><label class="rural-field">Project type<select class="rural-select" id="design-project">${projectTypes.map(p=>`<option value="${p.id}">${esc(p.label)}</option>`).join('')}</select></label><button class="button primary" id="generate-guide">Apply selection ${icon('arrow')}</button><p id="design-input-status" class="design-input-status" role="status" aria-live="polite"></p></div><div class="design-layout"><section class="design-main" id="design-main" aria-label="Architectural decision board"></section><aside class="design-evidence" id="design-evidence" aria-label="Decision and source inspector"></aside></div><div class="design-boundary"><span>Conceptual design study · Synthetic observations · No measured performance or adopted rule.</span><button class="rural-toolbar-button" id="preview-guide">${icon('print')} Preview / print guide</button></div>`}
function renderDesign(){app.innerHTML=shell(designBody())+'<section class="rural-print" id="rural-print-output" aria-label="Printable source-led design guide"></section>';bindCommon();$('#design-village').value=guideVillageId;$('#design-project').value=projectType;$('#generate-guide').onclick=()=>{pauseForUser();guideVillageId=$('#design-village').value;projectType=$('#design-project').value;generatedGuide=buildDesignGuide(guideVillageId,projectType);updateDesign();updateDesignInputStatus();toast('The four teaching prompts now use '+generatedGuide.village.name+' and '+generatedGuide.projectType.label.toLowerCase()+'.')};const inputsChanged=()=>{pauseForUser();updateDesignInputStatus()};$('#design-village').onchange=inputsChanged;$('#design-project').onchange=inputsChanged;all('[data-prompt]').forEach(b=>b.onclick=()=>{pauseForUser();activeRecommendation=Number(b.dataset.prompt);updateDesign()});$('#preview-guide').onclick=previewGuide;updateDesign();updateDesignInputStatus()}
function designHasPendingInputs(){return $('#design-village').value!==generatedGuide.village.id||$('#design-project').value!==generatedGuide.projectType.id}
function updateDesignInputStatus(){const pending=designHasPendingInputs(),g=generatedGuide;$('#design-input-status').textContent=pending?`Selection changed. Update the guide to apply it. The displayed prompts still use ${g.village.name} / ${g.projectType.label}.`:`Current guide: ${g.village.name} / ${g.projectType.label}.`;$('#design-input-status').classList.toggle('pending',pending);$('#preview-guide').disabled=pending;$('#preview-guide').setAttribute('aria-describedby','design-input-status');$('#generate-guide').setAttribute('aria-describedby','design-input-status');$('#open-rural-guide').setAttribute('aria-describedby','design-input-status rural-guide-description')}
function updateDesign(){
 const g=generatedGuide,r=g.recommendations[activeRecommendation],focus=r.category,component=categories.find(c=>c.id===focus);
 const outputs=['Assess compatibility','Study water shedding','Test the spatial fit',g.projectType.id==='renovation'?'Investigate condition':g.projectType.id==='public'?'Explore shared access':'Test organisation'];
 $('#design-main').innerHTML=`<div class="decision-board-head"><div><span class="rural-eyebrow">ARCHITECTURAL DECISION BOARD</span><h2>${esc(g.village.name)} <small>${esc(g.village.climate)}</small></h2></div><div class="decision-views" role="group" aria-label="Decision board view">${[['study','Study + detail'],['diagram','Diagram']].map(([id,label])=>`<button data-decision-view="${id}" class="${designBoardView===id?'active':''}" aria-pressed="${designBoardView===id}">${label}</button>`).join('')}</div></div>
 <nav class="decision-tools" aria-label="Select a design prompt">${g.recommendations.map((item,i)=>`<button class="${i===activeRecommendation?'active':''}" data-prompt="${i}" aria-pressed="${i===activeRecommendation}"><span class="decision-tool-number">0${i+1}</span>${icon(item.id==='project'?'guide':categories.find(c=>c.id===item.category).symbol)}<span>${['Materials','Roof','Layout','Project brief'][i]}</span></button>`).join('')}</nav>
 <div class="design-scene ${designBoardView==='diagram'?'diagram-view':''} ${activeRecommendation===3?'project-scope':''}" data-decision-focus="${focus}">${boardHtml(g.village,focus,{view:designBoardView,id:'decision'})}${designBoardView==='study'?`<div class="decision-detail-layer" aria-hidden="true"><div class="detail-layer-head">${icon(component.symbol)}<span>${activeRecommendation===3?'Project scope':esc(component.label)} / schematic detail</span></div>${drawing(g.village,focus,'detail')}</div>`:''}<div class="decision-scene-label"><span class="decision-live-dot"></span>${activeRecommendation===3?'PROJECT INPUT':esc(component.label.toUpperCase())} IN FOCUS</div><span class="decision-scene-stamp">Interpretive study · No scale</span></div>
 <div class="decision-pipeline" aria-label="Trace the decision from input to output"><div><small>${r.evidence.length?'01 / Observation':'01 / Selected project type'}</small><strong>${r.evidence.length?r.evidence.map(o=>o.id).join(' · '):esc(g.projectType.label)}</strong></div>${icon('arrow').replace('<svg ','<svg class="chain-arrow" ')}<div><small>02 / Explicit rule</small><strong>${esc(r.title)}</strong></div>${icon('arrow').replace('<svg ','<svg class="chain-arrow" ')}<div><small>03 / Output to investigate</small><strong>${esc(outputs[activeRecommendation])}</strong></div></div>`;
 $('#design-evidence').innerHTML=`<div class="decision-inspector-head"><span>DECISION INSPECTOR</span><strong>0${activeRecommendation+1} / 04</strong></div><div class="decision-inspector-body"><div class="decision-inspector-type">${esc(r.basis)}</div><h2>${esc(r.title)}</h2><p class="decision-action">${esc(r.action)}</p><div class="decision-why"><h3>Why this appears</h3><p>${esc(r.reason)}</p></div><section class="decision-records"><h2>Source evidence <span>${r.evidence.length} record${r.evidence.length===1?'':'s'}</span></h2>${r.evidence.length?r.evidence.map(o=>`<details class="decision-source"><summary><span class="record-id">${o.id}</span><strong>${esc(o.title)}</strong>${icon('chevron')}</summary><div><p>${esc(o.text)}</p><small>Sample.html · observation ${o.sourceIndex} / 10 · synthetic</small><a href="${FIELD}village-atlas/?v=${g.village.id}&obs=${o.id}">Open source record ${icon('arrow')}</a></div></details>`).join(''):`<div class="decision-source-note"><p>This action comes from the selected brief, not a village observation. No real condition survey, site brief or accessibility assessment is supplied.</p><strong>${esc(g.projectType.label)}</strong></div>`}</section><div class="decision-next"><span>Use the next prompt</span><p>Select a component above the board. Compare the source, the named rule and the question it produces.</p></div></div>`;
 all('[data-prompt]').forEach(b=>b.onclick=()=>{pauseForUser();activeRecommendation=Number(b.dataset.prompt);updateDesign();$('[data-prompt="'+activeRecommendation+'"]')?.focus({preventScroll:true})});
 all('[data-decision-view]').forEach(b=>b.onclick=()=>{pauseForUser();designBoardView=b.dataset.decisionView;updateDesign();$('[data-decision-view="'+designBoardView+'"]')?.focus({preventScroll:true})});bindImages();
}
function guidePreviewContent(){const g=generatedGuide;return `<div class="rural-status"><strong>Synthetic guide</strong><span>${esc(g.village.name)} / ${esc(g.projectType.label)}</span></div><p style="margin-top:16px">Each prompt keeps its reason and evidence with it. This is a read-only teaching report, not an assessment of a real site.</p><div class="guide-preview-list">${g.recommendations.map(r=>`<section class="guide-preview-item"><h3>${esc(r.title)}</h3><p>${esc(r.action)}</p><p><strong>Reason:</strong> ${esc(r.reason)}</p><p><strong>Basis:</strong> ${r.evidence.length?r.evidence.map(o=>o.id).join(' · '):'Selected project type; no village observation is claimed'}</p></section>`).join('')}</div><p>${esc(g.notice)}</p><button class="button primary" id="print-rural-guide" style="margin-top:18px">${icon('print')} Print or save PDF</button>`}
function previewGuide(){pauseForUser();if(designHasPendingInputs()){toast('Update the guide to apply your selection before previewing or printing.');$('#generate-guide').focus();return}dialog('Source-led design guide',guidePreviewContent());$('#print-rural-guide').onclick=printGuide}
function prepareGuidePrint(){const g=generatedGuide;$('#rural-print-output').innerHTML=`<img src="${ASSETS}barchinet-global.svg" alt="Barchinet Global"><div class="print-eyebrow">Rural Architecture / Design Guide / Synthetic teaching report</div><h1>${esc(g.village.name)}</h1><p>${esc(g.village.climate)} · ${esc(g.projectType.label)}</p><p>${esc(provenance.notice)}</p>${designHasPendingInputs()?`<p><strong>Unapplied selection:</strong> This report contains the displayed guide for ${esc(g.village.name)} / ${esc(g.projectType.label)}, not the changed selector values.</p>`:''}${g.recommendations.map(r=>`<section class="print-recommendation"><h2>${esc(r.title)}</h2><p>${esc(r.action)}</p><p><strong>Reason:</strong> ${esc(r.reason)}</p><div class="print-evidence">${r.evidence.length?r.evidence.map(o=>`<p><strong>${o.id} · ${esc(o.title)}:</strong> ${esc(o.text)}<br><small>Sample.html · ${esc(g.village.name)} · observation ${o.sourceIndex} / 10 · translated synthetic record</small></p>`).join(''):'<p>Basis: selected project type. This is not a village observation.</p>'}</div></section>`).join('')}<p>${esc(g.notice)}</p><section class="print-references"><h2>Source, limits and method references</h2><p>${esc(provenance.source)}. No coordinates, field dates, reviewers or measured performance are supplied. Public references inform documentation methods, not the fictional observations.</p>${atlasBibliography.map(r=>`<p class="print-reference">${r.authors.map(esc).join('; ')} (${esc(r.year)}). <strong>${esc(r.title)}</strong>. ${esc(r.publisher)}. ${esc(r.url)}<br>Purpose: ${esc(r.usedFor)}<br>Limit: ${esc(r.limitation)}</p>`).join('')}</section>`}
async function printGuide(){if(designHasPendingInputs()){toast('Update the guide before printing.');return}prepareGuidePrint();try{await $('#rural-print-output img')?.decode?.()}catch{}window.print()}

/* A guide operates the workspace: it changes the real selected component,
 * comparison lens or recommendation. It never writes or stores visitor data.
 */

const guidedExamples={
 'village-atlas':{title:'Trace a roof back to its record',outcome:'Explore Cheshmeh-sar through its roof, material and settlement records.'},
 'village-comparison':{title:'Compare two architectural contexts',outcome:'Read Cheshmeh-sar beside Aftab-dasht across four evidence-linked dimensions.'},
 'design-guide':{title:'Follow a prompt from source to rule',outcome:'Inspect a house-upgrade guide for Meh-darreh, including the prompt supplied by the project type.'},
};
function syncAtlasSelection(){ $('#atlas-context').innerHTML=villageContext();bindAtlasControls();$('#atlas-search').value=query;$('#atlas-category').value=category;all('[data-board-view]').forEach(b=>{b.classList.toggle('active',b.dataset.boardView===boardView);b.setAttribute('aria-pressed',String(b.dataset.boardView===boardView))});updateAtlas() }
function startGuidedExample(){
 pauseGuide();
 if(appId==='village-atlas'){
  guideExampleSnapshot={villageId,query,category,selectedObservation,boardView};
  villageId='cheshmeh-sar';query='';category='';selectedObservation=getVillage(villageId).observations[0].id;boardView='index';syncAtlasSelection();
 }else if(appId==='village-comparison'){
  guideExampleSnapshot={leftId,rightId,dimension};leftId='cheshmeh-sar';rightId='aftab-dasht';dimension='materials';$('#compare-a').value=leftId;$('#compare-b').value=rightId;updateComparison();
 }else{
  guideExampleSnapshot={guideVillageId,projectType,activeRecommendation,designBoardView,generatedGuide,pendingVillage:$('#design-village').value,pendingProject:$('#design-project').value};
  guideVillageId='meh-darreh';projectType='renovation';activeRecommendation=0;designBoardView='study';generatedGuide=buildDesignGuide(guideVillageId,projectType);$('#design-village').value=guideVillageId;$('#design-project').value=projectType;updateDesign();updateDesignInputStatus();
 }
 guideStep=0;guideOpen=true;if(motion)document.body.classList.remove('rural-paused');applyGuideStep();$('#rural-guide-play')?.focus({preventScroll:true});
}
function returnFromGuidedExample(){
 const saved=guideExampleSnapshot;if(!saved)return;pauseGuide();guideOpen=false;guideExampleSnapshot=null;guideStep=0;
 if(appId==='village-atlas'){({villageId,query,category,selectedObservation,boardView}=saved);syncAtlasSelection()}
 else if(appId==='village-comparison'){({leftId,rightId,dimension}=saved);$('#compare-a').value=leftId;$('#compare-b').value=rightId;updateComparison()}
 else{({guideVillageId,projectType,activeRecommendation,designBoardView,generatedGuide}=saved);$('#design-village').value=saved.pendingVillage;$('#design-project').value=saved.pendingProject;updateDesign();updateDesignInputStatus()}
 if(motion)document.body.classList.remove('rural-paused');renderCoach();$('#open-rural-guide').focus({preventScroll:true});
}

function coachHtml(){const task=guidedExamples[appId];return `<section class="rural-guide" id="rural-coach"><div class="rural-guide-top"><div><h2>${esc(task.title)}</h2><p id="rural-guide-description">${esc(task.outcome)} Return afterwards to restore your previous selections.</p></div><div class="rural-guide-actions"><button class="rural-toolbar-button" id="open-rural-guide" aria-expanded="false" aria-controls="rural-guide-body" aria-describedby="rural-guide-description">${icon('play')} Try guided example</button><label class="rural-motion"><input type="checkbox" id="rural-motion" ${motion?'checked':''}> Motion</label></div></div><div class="rural-guide-body" id="rural-guide-body" hidden></div></section>`}
function steps(){if(appId==='village-atlas'){const v=getVillage(villageId);return [{title:'Start with the context',text:`${v.name} is fictional. Its profile describes ${v.climate.toLowerCase()} conditions, not a measured climate record. The index shows a selectable study, not a real region.`,category:'materials',view:'index'},{title:'Inspect the roof record',text:'The Roof component is selected in the actual observation browser. Read the record and distinguish its intended role from a measured performance result.',category:'roof',view:'study'},{title:'Read the material evidence',text:'The Materials component is selected. The numbered point links to this synthetic description; the image does not serve as a field photograph or measured drawing.',category:'materials',view:'diagram'},{title:'Connect the building and the pattern',text:'The Settlement records are selected. Ask what cultural, site and field evidence would be needed before applying this pattern elsewhere.',category:'settlement',view:'study'}]}if(appId==='village-comparison')return [{title:'Compare two contexts',text:'Read the two selected villages and their material records. This is a description of different fictional contexts, not a test of which one is better.',category:'materials'},{title:'Follow a roof difference',text:'The Roof lens is now active on both study boards. Use either evidence ID to inspect the exact synthetic observation.',category:'roof'},{title:'Read the courtyard relationship',text:'The Courtyard lens is now selected. Compare how the profiles describe enclosure or openness before inferring a design response.',category:'courtyard'},{title:'Return to the settlement',text:'The Settlement lens is selected. Geographic closeness is not evidence of cultural or architectural similarity, and these index positions are not geographic.',category:'settlement'}];return [{title:'Start from source records',text:'The Materials prompt is selected. Its source record IDs are visible on the left of the evidence chain and the full descriptions appear beside it.',recommendation:0},{title:'See the explicit rule',text:'The Roof prompt is selected. Follow the records through the named teaching rule to a contextual question; no simulation or local design approval is implied.',recommendation:1},{title:'Keep relationships in view',text:'The layout prompt combines courtyard and settlement observations. Its evidence remains available instead of becoming an unexplained recommendation.',recommendation:2},{title:'Identify the non-observation input',text:'The project-type prompt is selected. It correctly shows no village evidence records: the chosen brief supplies this teaching action.',recommendation:3}]}
function applyGuideStep(){if(appId==='village-comparison'&&leftId===rightId){pauseGuide();guideOpen=false;renderCoach();toast('Choose two different villages before starting the walkthrough.');return}const step=steps()[guideStep];if(appId==='village-atlas'){query='';category=step.category;boardView=step.view;selectedObservation=getVillage(villageId).observations.find(o=>o.category===category)?.id;$('#atlas-search').value='';$('#atlas-category').value=category;all('[data-board-view]').forEach(b=>{b.classList.toggle('active',b.dataset.boardView===boardView);b.setAttribute('aria-pressed',String(b.dataset.boardView===boardView))});updateAtlas()}else if(appId==='village-comparison'){dimension=step.category;updateComparison()}else{activeRecommendation=step.recommendation;updateDesign()}renderCoach();const focusTarget=$(appId==='village-atlas'?'.rural-study':appId==='village-comparison'?'.comparison-scenes':'.design-main');focusTarget?.scrollIntoView?.({behavior:motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches?'smooth':'auto',block:'start'})}
function pauseGuide(){guidePlaying=false;clearInterval(guideTimer);$('#rural-coach')?.classList.remove('is-playing');document.body.classList.add('rural-paused')}
function pauseForUser(){if(guideOpen){pauseGuide();guideOpen=false;renderCoach()}if(motion)document.body.classList.remove('rural-paused')}
function renderCoach(){const focusedControl=document.activeElement?.id,host=$('#rural-guide-body');$('#open-rural-guide').setAttribute('aria-expanded',String(guideOpen));$('#rural-coach').classList.toggle('is-walkthrough',guideOpen);document.body.classList.toggle('rural-walkthrough-active',guideOpen);host.hidden=!guideOpen;$('#open-rural-guide').innerHTML=icon(guideExampleSnapshot?'back':'play')+(guideExampleSnapshot?'Return to my view':'Try guided example');$('#rural-guide-description').textContent=guideExampleSnapshot?(guideOpen?'Example active. Your previous selections are kept; return to restore them.':'Example paused. Explore freely, or return to restore your previous selections.'):guidedExamples[appId].outcome+' Return afterwards to restore your previous selections.';if(!guideOpen)return;const step=steps()[guideStep];host.innerHTML=`<div class="rural-guide-progress"><span class="rural-guide-step">Step ${guideStep+1} / 4</span><div class="rural-guide-dots">${steps().map((_,i)=>`<span class="${i<=guideStep?'current':''}"></span>`).join('')}</div><div class="rural-guide-controls"><button id="rural-guide-back" aria-label="Previous walkthrough step" ${guideStep===0?'disabled':''}>${icon('back')}</button><button id="rural-guide-play" aria-label="${guidePlaying?'Pause':'Play'} walkthrough">${icon(guidePlaying?'pause':'play')}</button><button id="rural-guide-next" aria-label="Next walkthrough step" ${guideStep===3?'disabled':''}>${icon('arrow')}</button><button id="rural-guide-replay" aria-label="Restart walkthrough">${icon('replay')}</button></div></div><div class="rural-guide-copy" role="status" aria-live="polite" aria-atomic="true"><h3>${esc(step.title)}</h3><p>${esc(step.text)}</p><span class="guide-action-result">Workspace focus: ${esc(appId==='design-guide'?generatedGuide.recommendations[activeRecommendation].title:categories.find(c=>c.id===(appId==='village-atlas'?category:dimension))?.label||'Context')}</span></div>`;$('#rural-guide-back').onclick=()=>{pauseGuide();if(motion)document.body.classList.remove('rural-paused');guideStep=Math.max(0,guideStep-1);applyGuideStep()};$('#rural-guide-next').onclick=()=>{pauseGuide();if(motion)document.body.classList.remove('rural-paused');guideStep=Math.min(3,guideStep+1);applyGuideStep()};$('#rural-guide-replay').onclick=()=>{pauseGuide();if(motion)document.body.classList.remove('rural-paused');guideStep=0;applyGuideStep()};$('#rural-guide-play').onclick=()=>{if(guidePlaying){pauseGuide();renderCoach();return}if(!motion||matchMedia('(prefers-reduced-motion: reduce)').matches){toast('Motion is off. Previous and Next keep the same workspace steps available.');return}if(guideStep===3)guideStep=0;guidePlaying=true;document.body.classList.remove('rural-paused');$('#rural-coach').classList.add('is-playing');applyGuideStep();guideTimer=setInterval(()=>{if(guideStep<3){guideStep++;applyGuideStep()}else{pauseGuide();renderCoach()}},8500)};if(focusedControl?.startsWith('rural-guide-')){const preferred=$('#'+focusedControl);(preferred&&!preferred.disabled?preferred:$('#rural-guide-play'))?.focus({preventScroll:true})}}
function bindCommon(){const sourceLink=$('a[href="#rural-sources"]');if(sourceLink)sourceLink.onclick=()=>{$('#rural-sources').open=true};$('#rural-maturity').onclick=showMaturity;$('#open-rural-guide').onclick=()=>{if(guideExampleSnapshot)returnFromGuidedExample();else startGuidedExample()};$('#rural-motion').onchange=e=>{motion=e.target.checked;document.body.classList.toggle('rural-no-motion',!motion);if(!motion){pauseGuide();if(guideOpen)renderCoach()}};$('#rural-dialog').addEventListener('click',e=>{if(e.target===$('#rural-dialog'))$('#rural-dialog').close()})}
function toast(text){const el=$('#rural-toast');el.textContent=text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,5000)}
function dialog(title,content){const el=$('#rural-dialog');el.innerHTML=`<div class="rural-dialog-inner"><div class="rural-dialog-head"><h2 id="rural-dialog-title">${esc(title)}</h2><button class="icon-button" id="rural-dialog-close" aria-label="Close dialog">${icon('close')}</button></div>${content}</div>`;$('#rural-dialog-close').onclick=()=>el.close();if(!el.open)el.showModal()}
function showMaturity(){pauseForUser();dialog('Research maturity',`<div class="rural-status"><strong>${esc(atlasMaturity.label)}</strong><span>Level 1 / ${atlasMaturity.levels.length}</span></div><p style="margin-top:16px">${esc(atlasMaturity.description)}</p><div class="maturity-evidence"><strong>Project-specific evidence register</strong><p>No field survey, accepted local guidance, pilot or independent validation is recorded.</p></div><p>The following criteria describe evidence needed to advance, not completed milestones or external certification.</p><ol class="maturity-ladder">${atlasMaturity.levels.map(l=>`<li class="${l.level===1?'current':''}"><span class="ladder-number">${String(l.level).padStart(2,'0')}</span><div><h3>${esc(l.title)} ${l.level===1?'<span>Current recorded level</span>':''}</h3><ul>${l.evidenceRequired.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div></li>`).join('')}</ol>`)}
function sourcesHtml(){return `<details class="rural-notes" id="rural-sources"><summary>Source records, boundaries & method references ${icon('chevron')}</summary><div class="rural-notes-grid"><div><h3>What is preserved</h3><p>${esc(provenance.source)}. Each village retains its ten separate observations. The interface exposes observation IDs and keeps recommendation rules separate from the records.</p><p style="margin-top:11px">${esc(provenance.notice)}</p></div><div><h3>What real records would need</h3><ul>${provenance.realDataNeeds.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><p style="margin-top:11px">${esc(provenance.boundary)}</p></div></div><div class="academic-sources"><p class="reference-notice" style="padding-top:18px">The publications below inform documentation and conservation methods. They provide none of the fictional village observations, certify no generated design prompt, and establish no partnership or market demand.</p>${atlasBibliography.map(r=>`<article class="reference-entry" style="margin:0 20px"><div class="reference-type">${esc(r.type)} / ${esc(r.year)}</div><h4><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ${icon('up')}</a></h4><p class="reference-citation">${r.authors.map(esc).join('; ')} (${esc(r.year)}). ${esc(r.publisher)}.</p><dl><div><dt>What this informs</dt><dd>${esc(r.usedFor)}</dd></div><div><dt>Scope & limitation</dt><dd>${esc(r.limitation)}</dd></div></dl></article>`).join('')}</div></details>`}

motionPreference.addEventListener?.('change',event=>{if(!event.matches)return;motion=false;document.body.classList.add('rural-no-motion');const toggle=$('#rural-motion');if(toggle)toggle.checked=false;if(guidePlaying)pauseGuide();if(guideOpen)renderCoach()});
window.addEventListener('beforeprint',()=>{if(guidePlaying){pauseGuide();renderCoach()}if(appId==='design-guide')prepareGuidePrint()});
document.body.classList.toggle('rural-design-print',appId==='design-guide');
document.body.classList.toggle('rural-app-mode',Boolean(appInfo));
document.addEventListener('visibilitychange',()=>{if(document.hidden&&guidePlaying){pauseGuide();renderCoach()}});
document.body.classList.toggle('rural-no-motion',!motion);
if(!appInfo)renderCollection();else if(appId==='village-atlas')renderAtlas();else if(appId==='village-comparison')renderComparison();else renderDesign();
